1008	/// Creates a new gitignore matcher for the directory given.
1009	///
1010	/// The matcher is meant to match files below `dir`.
1011	/// Ignore globs are extracted from each of the file names relative to
1012	/// `dir_for_ignorefile` in the order given (earlier names have lower
1013	/// precedence than later names).
1014	///
1015	/// I/O errors are ignored.
1016	pub(crate) fn create_gitignore<T: AsRef<OsStr>>(
1017	    dir: &Path,
1018	    dir_for_ignorefile: &Path,
1019	    names: &[T],
1020	    case_insensitive: bool,
1021	) -> (Gitignore, Option<Error>) {
1022	    let mut builder = GitignoreBuilder::new(dir);
1023	    let mut errs = PartialErrorBuilder::default();
1024	    builder.case_insensitive(case_insensitive).unwrap();
1025	    for name in names {
1026	        let gipath = dir_for_ignorefile.join(name.as_ref());
1027	        // This check is not necessary, but is added for performance. Namely,
1028	        // a simple stat call checking for existence can often be just a bit
1029	        // quicker than actually trying to open a file. Since the number of
1030	        // directories without ignore files likely greatly exceeds the number
1031	        // with ignore files, this check generally makes sense.
1032	        //
1033	        // However, until demonstrated otherwise, we speculatively do not do
1034	        // this on Windows since Windows is notorious for having slow file
1035	        // system operations. Namely, it's not clear whether this analysis
1036	        // makes sense on Windows.
1037	        //
1038	        // For more details: https://github.com/BurntSushi/ripgrep/pull/1381
1039	        if cfg!(windows) || gipath.exists() {
1040	            errs.maybe_push_ignore_io(builder.add(gipath));
1041	        }
1042	    }
1043	    let gi = match builder.build() {
1044	        Ok(gi) => gi,
1045	        Err(err) => {
1046	            errs.push(err);
1047	            GitignoreBuilder::new(dir).build().unwrap()
1048	        }
1049	    };
1050	    (gi, errs.into_error_option())
1051	}
