409	/// The result of a glob match.
410	///
411	/// The type parameter `T` typically refers to a type that provides more
412	/// information about a particular match. For example, it might identify
413	/// the specific gitignore file and the specific glob pattern that caused
414	/// the match.
415	#[derive(Clone, Debug)]
416	pub enum Match<T> {
417	    /// The path didn't match any glob.
418	    None,
419	    /// The highest precedent glob matched indicates the path should be
420	    /// ignored.
421	    Ignore(T),
422	    /// The highest precedent glob matched indicates the path should be
423	    /// whitelisted.
424	    Whitelist(T),
425	}
426	
427	impl<T> Match<T> {
428	    /// Returns true if the match result didn't match any globs.
429	    pub fn is_none(&self) -> bool {
430	        match *self {
431	            Match::None => true,
432	            Match::Ignore(_) | Match::Whitelist(_) => false,
433	        }
434	    }
435	
436	    /// Returns true if the match result implies the path should be ignored.
437	    pub fn is_ignore(&self) -> bool {
438	        match *self {
439	            Match::Ignore(_) => true,
440	            Match::None | Match::Whitelist(_) => false,
441	        }
442	    }
443	
444	    /// Returns true if the match result implies the path should be
445	    /// whitelisted.
446	    pub fn is_whitelist(&self) -> bool {
447	        match *self {
448	            Match::Whitelist(_) => true,
449	            Match::None | Match::Ignore(_) => false,
450	        }
451	    }
452	
453	    /// Inverts the match so that `Ignore` becomes `Whitelist` and
454	    /// `Whitelist` becomes `Ignore`. A non-match remains the same.
455	    pub fn invert(self) -> Match<T> {
456	        match self {
457	            Match::None => Match::None,
458	            Match::Ignore(t) => Match::Whitelist(t),
459	            Match::Whitelist(t) => Match::Ignore(t),
460	        }
461	    }
462	
463	    /// Return the value inside this match if it exists.
464	    pub fn inner(&self) -> Option<&T> {
465	        match *self {
466	            Match::None => None,
467	            Match::Ignore(ref t) => Some(t),
468	            Match::Whitelist(ref t) => Some(t),
469	        }
470	    }
471	
472	    /// Apply the given function to the value inside this match.
473	    ///
474	    /// If the match has no value, then return the match unchanged.
475	    pub fn map<U, F: FnOnce(T) -> U>(self, f: F) -> Match<U> {
476	        match self {
477	            Match::None => Match::None,
478	            Match::Ignore(t) => Match::Ignore(f(t)),
479	            Match::Whitelist(t) => Match::Whitelist(f(t)),
480	        }
481	    }
482	
483	    /// Return the match if it is not none. Otherwise, return other.
484	    pub fn or(self, other: Self) -> Self {
485	        if self.is_none() { other } else { self }
486	    }
487	}
