105	impl IncrementalIgnore {
106	    pub(crate) fn new(
107	        root: PathBuf,
108	        ignore: Ignore,
109	        options: IncrementalIgnoreOptions,
110	    ) -> IncrementalIgnore {
111	        // File traversal special cases `-` to search stdin, so we recognize
112	        // it here for completeness too. In particular, we really want
113	        // `WalkBuilder::build_matchers` to return a matcher for every root,
114	        // even when it's a simple file (handled automatically) or when it's
115	        // stdin (necessarily special cased).
