120	            RootIgnore::Stdin
121	        } else {
122	            RootIgnore::Unloaded(ignore)
123	        };
124	        IncrementalIgnore {
125	            root,
126	            normalized_root: OnceLock::new(),
127	            ignore,
128	            dirs: HashMap::new(),
129	            options,
130	        }
131	    }
