224	    fn matched_with_errors_impl(
225	        &mut self,
226	        relative: &Path,
227	        is_dir: bool,
228	        errs: &mut PartialErrorBuilder,
229	    ) -> IncrementalMatch {
230	        // We short-circuit here when our matcher corresponds to `Stdin` in
