436	/// The result of an incremental match.
437	///
438	/// This is similar to [`Match`] in that it reports whether a file path should
439	/// be ignored, whitelisted or didn't match anything at all. It also has extra
440	/// data, such as whether a directory matched but should not be descended into.
441	///
442	/// Generally speaking, callers that only care about specific files can stick
443	/// to the `is_none()`, `is_ignore()` or `is_whitelist()` predicates. Directory
444	/// entries are more complicated because we sometimes want to yield directories
445	/// to descend into, but not actually visit (e.g., for the minimum depth
446	/// filter). Or, we may want to yield a directory to visit but not descend into
447	/// (e.g., for the maximum depth filter).
448	#[derive(Clone, Debug)]
449	pub struct IncrementalMatch {
450	    mat: Match<()>,
451	    should_descend: bool,
452	    is_within_depth: bool,
453	}
454	
455	impl IncrementalMatch {
456	    fn none(is_dir: bool) -> IncrementalMatch {
457	        IncrementalMatch {
458	            mat: Match::None,
459	            should_descend: is_dir,
460	            is_within_depth: true,
461	        }
462	    }
463	
464	    fn ignore() -> IncrementalMatch {
465	        IncrementalMatch {
466	            mat: Match::Ignore(()),
467	            should_descend: false,
468	            is_within_depth: true,
469	        }
470	    }
471	
472	    fn from_match(mat: Match<()>, is_dir: bool) -> IncrementalMatch {
473	        let should_descend = is_dir && !mat.is_ignore();
474	        IncrementalMatch { mat, should_descend, is_within_depth: true }
475	    }
476	
477	    fn no_descent(self) -> IncrementalMatch {
478	        IncrementalMatch { should_descend: false, ..self }
479	    }
480	
481	    fn not_within_depth(self) -> IncrementalMatch {
482	        IncrementalMatch { is_within_depth: false, ..self }
483	    }
484	
485	    /// Returns true if the match result didn't match anything.
486	    pub fn is_none(&self) -> bool {
487	        self.mat.is_none()
488	    }
489	
490	    /// Returns true if the match result implies the path should be ignored.
491	    pub fn is_ignore(&self) -> bool {
492	        self.mat.is_ignore()
493	    }
494	
495	    /// Returns true if the match result implies the path should be
496	    /// whitelisted.
497	    pub fn is_whitelist(&self) -> bool {
498	        self.mat.is_whitelist()
499	    }
500	
501	    /// Returns true only when this match corresponds to a directory *and*
502	    /// whether the caller should look inside this directory for additional
503	    /// results.
504	    ///
505	    /// It is possible for a match to report `false` for
506	    /// [`IncrementalMatch::is_ignore`] _and_ `false` for
507	    /// [`IncrementalMatch::should_descend`]. This can occur, for example, when
508	    /// a maximum depth setting allows a directory through, but where none of
509	    /// its children entries should be visited.
510	    ///
511	    /// This is always `false` for a file path that does *not* correspond to a
512	    /// directory.
513	    pub fn should_descend(&self) -> bool {
514	        self.should_descend
515	    }
516	
517	    /// Returns true only when this result corresponds to an entry that is
518	    /// within the depth filter.
519	    ///
520	    /// This is `false` when a path corresponds to a directory and is less than
521	    /// the minimum depth. In this case, callers should continue looking inside
522	    /// that directory.
523	    ///
524	    /// This is always `true` for a match corresponding to a file path that
525	    /// isn't a directory.
526	    pub fn is_within_depth(&self) -> bool {
527	        self.is_within_depth
528	    }
529	
530	    /// Inverts the match so that `Ignore` becomes `Whitelist` and
531	    /// `Whitelist` becomes `Ignore`. A non-match remains the same.
532	    pub fn invert(self) -> IncrementalMatch {
533	        IncrementalMatch { mat: self.mat.invert(), ..self }
534	    }
535	}
536	
537	/// Return a lexically normalized absolute representation of `path`.
538	///
539	/// This collapses `.` and `..`, but intentionally does not canonicalize or
540	/// resolve symlinks. Ignore rules apply to the lexical path, and resolving a
541	/// symlink below a root could move the result outside of that root.
542	fn normalize_absolute(path: &Path) -> Option<PathBuf> {
543	    let absolute = std::path::absolute(path).ok()?;
544	    let mut normalized = PathBuf::new();
545	    for component in absolute.components() {
546	        match component {
547	            std::path::Component::CurDir => {}
548	            std::path::Component::ParentDir => {
549	                normalized.pop();
550	            }
551	            _ => normalized.push(component.as_os_str()),
552	        }
553	    }
554	    Some(normalized)
555	}
