#[test]
fn refresh_observes_added_and_deleted_ignore_files() {
    let td = tmpdir();
    mkdirp(td.path().join("a"));

    let mut b = builder(td.path());
    b.add_custom_ignore_filename(".rgignore");
    let mut m = one_matcher(&b);
